/**
 * SmartBow Zero — Phase 1C Real OpenCV Parity Test Suite (test/arucoParity.ts)
 *
 * Verifies the TypeScript ArUco detector (`src/lib/arucoDetector.ts`), dictionary
 * (`src/lib/arucoDict.ts`), and optical diagnostic state machine (`src/lib/opticalDiagnostics.ts`)
 * against ground-truth vectors generated by real Python OpenCV (`tools/gen_golden.py`).
 *
 * Run:
 *   python tools/gen_golden.py --out test/golden
 *   npx tsx test/arucoParity.ts
 */

import * as fs from 'fs';
import * as path from 'path';
import {
  ARUCO_DICT_4X4_50_BITS,
  REGISTERED_ARUCO_IDS,
  CLINICAL_RIM_MARKER_IDS,
  getFullMarkerGrid,
  decodeMarkerGrid,
  decodeMarkerGridWithConfidence,
} from '../src/lib/arucoDict';
import {
  MIN_CONTOUR_POINTS,
  MIN_BBOX_PX,
  MIN_SIDE_PX,
  MIN_AREA_PX2,
  MAX_BORDER_ERRORS,
  MAX_PROC_DIM,
  ADAPTIVE_FALLBACK_PROC_DIM,
  MIN_AUTO_PROC_DIM,
  PROC_FRAME_BUDGET_MS,
  detectArucoMarkersFromImageData,
  computeCoverTransform,
  mapVideoPointToCanvas,
  mapVideoCornersToCanvas,
  resetAdaptiveResolutionController,
  recordFrameProcessingDuration,
  getAdaptiveResolutionState,
} from '../src/lib/arucoDetector';
import {
  evaluateArucoPipelineDiagnostic,
  CLINICAL_MAXILLA_IDS,
  CLINICAL_MANDIBLE_IDS,
  CLINICAL_RIM_EXPECTED_IDS,
} from '../src/lib/opticalDiagnostics';

interface GoldenCase {
  id: string;
  category: string;
  width: number;
  height: number;
  byteOffset: number;
  byteLength: number;
  expectedIds: number[];
  plantedCorners: Record<string, number[][]>;
  opencvDetectedIds: number[];
  opencvCorners: number[][][];
  meta: Record<string, any>;
}

interface GoldenManifest {
  generator: string;
  opencvVersion: string;
  dictionary: string;
  totalCases: number;
  blobFile: string;
  dictionaryGrids: Record<string, number[][]>;
  cases: GoldenCase[];
}

function grayBufferToRgbaImageData(
  blob: Buffer,
  byteOffset: number,
  width: number,
  height: number
): { data: Uint8ClampedArray; width: number; height: number } {
  const rgba = new Uint8ClampedArray(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    const g = blob[byteOffset + i];
    const idx = i * 4;
    rgba[idx] = g;
    rgba[idx + 1] = g;
    rgba[idx + 2] = g;
    rgba[idx + 3] = 255;
  }
  return { data: rgba, width, height };
}

let passedAssertions = 0;
let failedAssertions = 0;

function check(condition: boolean, label: string, details: string = ''): void {
  if (condition) {
    passedAssertions++;
    console.log(`  [PASS] ${label}`);
  } else {
    failedAssertions++;
    console.error(`  [FAIL] ${label}${details ? ` — ${details}` : ''}`);
  }
}

function main(): void {
  const goldenDir = path.resolve(process.cwd(), 'test/golden');
  const manifestPath = path.join(goldenDir, 'manifest.json');
  if (!fs.existsSync(manifestPath)) {
    console.error(`ERROR: Golden manifest not found at ${manifestPath}. Run: python tools/gen_golden.py --out test/golden`);
    process.exit(1);
  }

  const manifest: GoldenManifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
  const blobPath = path.join(goldenDir, manifest.blobFile);
  const blob = fs.readFileSync(blobPath);

  console.log('====================================================================');
  console.log(`SMARTBOW ZERO — PHASE 1C OPENCV ARUCO PARITY SUITE (OpenCV ${manifest.opencvVersion})`);
  console.log(`Loaded ${manifest.totalCases} golden cases from ${manifestPath}`);
  console.log('====================================================================\n');

  // Verify F1-F3 Named Constants
  console.log('0. Phase 1C F1–F3 Named Configuration Constants & Adaptive Resolution Controller');
  check(
    MIN_CONTOUR_POINTS === 12 &&
      MIN_BBOX_PX === 8 &&
      MIN_SIDE_PX === 7 &&
      MIN_AREA_PX2 === 40 &&
      MAX_BORDER_ERRORS === 7 &&
      MAX_PROC_DIM === 1920 &&
      ADAPTIVE_FALLBACK_PROC_DIM === 1280 &&
      MIN_AUTO_PROC_DIM === 960 &&
      PROC_FRAME_BUDGET_MS === 45,
    '0a: F1–F3 named constants match exact Phase 1C specification',
    `MIN_CONTOUR_POINTS=${MIN_CONTOUR_POINTS}, MIN_BBOX_PX=${MIN_BBOX_PX}, MIN_SIDE_PX=${MIN_SIDE_PX}, MIN_AREA_PX2=${MIN_AREA_PX2}, MAX_BORDER_ERRORS=${MAX_BORDER_ERRORS}, MAX_PROC_DIM=${MAX_PROC_DIM}`
  );

  resetAdaptiveResolutionController();
  const initialResState = getAdaptiveResolutionState();
  for (let i = 0; i < 10; i++) recordFrameProcessingDuration(52); // > 45ms budget
  const afterStep1 = getAdaptiveResolutionState();
  for (let i = 0; i < 10; i++) recordFrameProcessingDuration(55); // > 45ms budget again
  const afterStep2 = getAdaptiveResolutionState();
  for (let i = 0; i < 10; i++) recordFrameProcessingDuration(60); // Should never drop below 960px
  const afterStep3 = getAdaptiveResolutionState();
  resetAdaptiveResolutionController();

  check(
    initialResState.activeMaxProcDim === 1920 &&
      afterStep1.activeMaxProcDim === 1280 &&
      afterStep2.activeMaxProcDim === 960 &&
      afterStep3.activeMaxProcDim === 960,
    '0b: F2 adaptive resolution controller starts at 1920px, steps to 1280px when 10-frame avg > 45ms, and never drops below 960px',
    `init=${initialResState.activeMaxProcDim}, step1=${afterStep1.activeMaxProcDim}, step2=${afterStep2.activeMaxProcDim}, step3=${afterStep3.activeMaxProcDim}`
  );

  // ---------------------------------------------------------------------------
  // 1. Dictionary Parity Across All 50 IDs (0–49)
  // ---------------------------------------------------------------------------
  console.log('\n1. Dictionary Parity Across All 50 OpenCV DICT_4X4_50 IDs (0–49)');
  let bitMatrixMatches = 0;
  for (let id = 0; id < 50; id++) {
    const cvGrid = manifest.dictionaryGrids[String(id)];
    const tsGrid = getFullMarkerGrid(id);
    const decoded = decodeMarkerGrid(tsGrid);
    const gridsIdentical =
      cvGrid &&
      tsGrid.length === 6 &&
      tsGrid.every((row, r) => row.every((val, c) => val === cvGrid[r][c])) &&
      decoded?.id === id &&
      decoded?.rotationDeg === 0;
    if (gridsIdentical) bitMatrixMatches++;
  }

  const dictCases = manifest.cases.filter((c) => c.category === 'DICT_PARITY_50');
  let dictRasterMatches = 0;
  let dictWrongIds = 0;
  for (const c of dictCases) {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);
    if (det.detectedIds.length === 1 && det.detectedIds[0] === c.expectedIds[0]) {
      dictRasterMatches++;
    } else if (det.detectedIds.some((id) => id !== c.expectedIds[0])) {
      dictWrongIds++;
    }
  }

  check(
    bitMatrixMatches === 50 && dictRasterMatches === 50 && dictWrongIds === 0 && Object.keys(ARUCO_DICT_4X4_50_BITS).length === 50,
    `1a: 50/50 dictionary parity (bit-for-bit grids=${bitMatrixMatches}/50, rasterized image decode=${dictRasterMatches}/50, wrong IDs=${dictWrongIds})`,
    `bitMatrixMatches=${bitMatrixMatches}, dictRasterMatches=${dictRasterMatches}`
  );

  // ---------------------------------------------------------------------------
  // 2–6. Single & Multi-Marker Dental-Rim Group Tests (IDs 3–10)
  // ---------------------------------------------------------------------------
  console.log('\n2–6. Dental-Rim Single & Multi-Marker Group Parity (IDs 3–6 Maxilla, IDs 7–10 Mandible)');
  const groupCategories: Array<{ cat: string; label: string; expected: number[] }> = [
    { cat: 'SINGLE_MAXILLA', label: '2: Single maxillary marker (ID 3)', expected: [3] },
    { cat: 'SINGLE_MANDIBLE', label: '3: Single mandibular marker (ID 7)', expected: [7] },
    { cat: 'GROUP_MAXILLA', label: '4: Complete maxillary group (IDs 3, 4, 5, 6)', expected: [3, 4, 5, 6] },
    { cat: 'GROUP_MANDIBLE', label: '5: Complete mandibular group (IDs 7, 8, 9, 10)', expected: [7, 8, 9, 10] },
    { cat: 'GROUP_BOTH', label: '6: Both maxillary & mandibular groups together (IDs 3–10)', expected: [3, 4, 5, 6, 7, 8, 9, 10] },
  ];

  for (const gc of groupCategories) {
    const c = manifest.cases.find((item) => item.category === gc.cat)!;
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);
    const exactMatch =
      det.detectedIds.length === gc.expected.length &&
      gc.expected.every((id, idx) => det.detectedIds[idx] === id);
    check(
      exactMatch,
      `${gc.label} — detected [${det.detectedIds.join(', ')}] (OpenCV: [${c.opencvDetectedIds.join(', ')}])`,
      `Expected ${JSON.stringify(gc.expected)}, got ${JSON.stringify(det.detectedIds)}`
    );
  }

  // ---------------------------------------------------------------------------
  // 7–10. Scale (8..60px) × Rotation (0°, 25°) × Blur (0, 0.8px) × Noise (sigma 2)
  // ---------------------------------------------------------------------------
  console.log('\n7–10. Scale (8–60 px) × Rotation (0°, 25°) × Blur (0, 0.8 px) × Noise (sigma 0, 2) Sweep');
  const sweepCases = manifest.cases.filter((c) => c.category === 'SWEEP_SCALE_ROT_BLUR_NOISE');

  let totalIncorrectIds = 0;
  let ge14OpenCvCount = 0;
  let ge14TsMatchedOpenCvCount = 0;
  let ge14TotalCases = 0;
  let ge14TsDetectedTotal = 0;

  let ge10OpenCvCount = 0;
  let ge10TsMatchedOpenCvCount = 0;
  let ge10TotalCases = 0;
  let ge10TsDetectedTotal = 0;

  const perSideStats: Record<number, { total: number; cvDetected: number; tsDetected: number; wrongId: number }> = {};

  for (const c of sweepCases) {
    const sidePx = c.meta.sidePx as number;
    if (!perSideStats[sidePx]) {
      perSideStats[sidePx] = { total: 0, cvDetected: 0, tsDetected: 0, wrongId: 0 };
    }
    perSideStats[sidePx].total++;

    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);

    const expectedId = c.expectedIds[0];
    const cvGotIt = c.opencvDetectedIds.includes(expectedId);
    const tsGotIt = det.detectedIds.includes(expectedId);
    const tsHasWrongId = det.detectedIds.some((id) => id !== expectedId);

    if (cvGotIt) perSideStats[sidePx].cvDetected++;
    if (tsGotIt) perSideStats[sidePx].tsDetected++;
    if (tsHasWrongId) {
      perSideStats[sidePx].wrongId++;
      totalIncorrectIds++;
    }

    if (sidePx >= 14) {
      ge14TotalCases++;
      if (tsGotIt) ge14TsDetectedTotal++;
      if (cvGotIt) {
        ge14OpenCvCount++;
        if (tsGotIt && !tsHasWrongId) ge14TsMatchedOpenCvCount++;
      }
    }
    if (sidePx >= 10) {
      ge10TotalCases++;
      if (tsGotIt) ge10TsDetectedTotal++;
      if (cvGotIt) {
        ge10OpenCvCount++;
        if (tsGotIt && !tsHasWrongId) ge10TsMatchedOpenCvCount++;
      }
    }
  }

  for (const [sideStr, st] of Object.entries(perSideStats)) {
    console.log(
      `  • Side ${sideStr.padStart(2, ' ')} px: TS detected ${st.tsDetected}/${st.total} (${((st.tsDetected / st.total) * 100).toFixed(1)}%) | OpenCV detected ${st.cvDetected}/${st.total} (${((st.cvDetected / st.total) * 100).toFixed(1)}%) | Wrong IDs: ${st.wrongId}`
    );
  }

  const ge14ParityPct = ge14OpenCvCount > 0 ? (ge14TsMatchedOpenCvCount / ge14OpenCvCount) * 100 : 100;
  const ge10ParityPct = ge10OpenCvCount > 0 ? (ge10TsMatchedOpenCvCount / ge10OpenCvCount) * 100 : 100;
  const ge10OverallPct = ge10TotalCases > 0 ? (ge10TsDetectedTotal / ge10TotalCases) * 100 : 100;

  check(
    ge14ParityPct === 100 && ge14TsDetectedTotal === ge14TotalCases && totalIncorrectIds === 0,
    `7a: Markers >= 14 px achieve 100% of OpenCV detections (${ge14TsMatchedOpenCvCount}/${ge14OpenCvCount} = ${ge14ParityPct.toFixed(1)}%, overall ${ge14TsDetectedTotal}/${ge14TotalCases}) with 100% correct IDs`,
    `ge14ParityPct=${ge14ParityPct.toFixed(2)}%, incorrectIds=${totalIncorrectIds}`
  );

  check(
    ge10ParityPct >= 90 && ge10OverallPct >= 90 && totalIncorrectIds === 0,
    `7b: Markers >= 10 px achieve >= 90% of OpenCV detections (${ge10TsMatchedOpenCvCount}/${ge10OpenCvCount} = ${ge10ParityPct.toFixed(1)}%, overall ${ge10TsDetectedTotal}/${ge10TotalCases} = ${ge10OverallPct.toFixed(1)}%) with 0 incorrect IDs`,
    `ge10ParityPct=${ge10ParityPct.toFixed(2)}%, ge10OverallPct=${ge10OverallPct.toFixed(2)}%`
  );

  // Explicit Breakdown for Rotations (8), Blur (9), and Noise (10) on >= 10px markers
  const rot25Cases = sweepCases.filter((c) => c.meta.sidePx >= 10 && c.meta.rotationDeg === 25);
  const rot25Detected = rot25Cases.filter((c) => {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    return detectArucoMarkersFromImageData(img).detectedIds.includes(c.expectedIds[0]);
  }).length;
  check(
    rot25Detected / rot25Cases.length >= 0.9,
    `8: Rotated 25° markers (>= 10 px) detected at ${rot25Detected}/${rot25Cases.length} (${((rot25Detected / rot25Cases.length) * 100).toFixed(1)}%)`,
    `rot25Detected=${rot25Detected}/${rot25Cases.length}`
  );

  const blur08Cases = sweepCases.filter((c) => c.meta.sidePx >= 10 && c.meta.blurSigma === 0.8);
  const blur08Detected = blur08Cases.filter((c) => {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    return detectArucoMarkersFromImageData(img).detectedIds.includes(c.expectedIds[0]);
  }).length;
  check(
    blur08Detected / blur08Cases.length >= 0.9,
    `9: Blurred 0.8 px markers (>= 10 px) detected at ${blur08Detected}/${blur08Cases.length} (${((blur08Detected / blur08Cases.length) * 100).toFixed(1)}%)`,
    `blur08Detected=${blur08Detected}/${blur08Cases.length}`
  );

  const noise2Cases = sweepCases.filter((c) => c.meta.sidePx >= 10 && c.meta.noiseSigma === 2);
  const noise2Detected = noise2Cases.filter((c) => {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    return detectArucoMarkersFromImageData(img).detectedIds.includes(c.expectedIds[0]);
  }).length;
  check(
    noise2Detected / noise2Cases.length >= 0.9,
    `10: Noisy sigma=2 markers (>= 10 px) detected at ${noise2Detected}/${noise2Cases.length} (${((noise2Detected / noise2Cases.length) * 100).toFixed(1)}%)`,
    `noise2Detected=${noise2Detected}/${noise2Cases.length}`
  );

  // ---------------------------------------------------------------------------
  // 11. Blank and Uniform Images
  // ---------------------------------------------------------------------------
  console.log('\n11. Blank and Uniform Images');
  const blankCases = manifest.cases.filter((c) => c.category === 'BLANK_UNIFORM');
  let blankFalsePositives = 0;
  for (const c of blankCases) {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);
    if (det.markers.length > 0) blankFalsePositives++;
  }
  check(
    blankCases.length === 5 && blankFalsePositives === 0,
    `11: All ${blankCases.length} blank/uniform images return 0 false positives`,
    `blankFalsePositives=${blankFalsePositives}`
  );

  // ---------------------------------------------------------------------------
  // 12. Incorrect DICT_6X6_250 Markers
  // ---------------------------------------------------------------------------
  console.log('\n12. Incorrect DICT_6X6_250 Markers Rejection');
  const wrongDictCases = manifest.cases.filter((c) => c.category === 'WRONG_DICT_6X6_250');
  let wrongDictFalsePositives = 0;
  let wrongDictClassified = 0;
  for (const c of wrongDictCases) {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);
    if (det.markers.length > 0) wrongDictFalsePositives++;
    if (det.failureCategory === 'WRONG_DICTIONARY_OR_ID' && det.candidateSummary.rejectedDictionary > 0) {
      wrongDictClassified++;
    }
  }
  check(
    wrongDictCases.length === 6 && wrongDictFalsePositives === 0 && wrongDictClassified === 6,
    `12: All ${wrongDictCases.length} foreign DICT_6X6_250 markers rejected with 0 false positives and WRONG_DICTIONARY_OR_ID classification`,
    `falsePos=${wrongDictFalsePositives}, classified=${wrongDictClassified}`
  );

  // ---------------------------------------------------------------------------
  // 13. 300 Seeded Random Block Images (Zero False Positives)
  // ---------------------------------------------------------------------------
  console.log('\n13. 300 Seeded Random Block Images');
  const randomCases = manifest.cases.filter((c) => c.category === 'RANDOM_BLOCKS_300');
  let randomFalsePositives = 0;
  for (const c of randomCases) {
    const img = grayBufferToRgbaImageData(blob, c.byteOffset, c.width, c.height);
    const det = detectArucoMarkersFromImageData(img);
    if (det.markers.length > 0) {
      randomFalsePositives++;
    }
  }
  check(
    randomCases.length === 300 && randomFalsePositives === 0,
    `13: 0 false positives across all ${randomCases.length} seeded random block images`,
    `randomFalsePositives=${randomFalsePositives}`
  );

  // ---------------------------------------------------------------------------
  // 14. Partial Group States & Deduplication
  // ---------------------------------------------------------------------------
  console.log('\n14. Partial Dental-Rim Group States & ID Deduplication');
  const partialDiag = evaluateArucoPipelineDiagnostic({
    cameraActive: true,
    cameraPoweredOn: true,
    cameraError: null,
    frameDiag: null,
    detectedIds: [3, 3, 5, 7, 8, 9, 9], // Contains duplicate IDs to verify deduplication
    faceDetected: true,
  });
  check(
    partialDiag.condition === 'MARKERS_DETECTED' &&
      partialDiag.maxillaGroupStatus.status === 'PARTIAL' &&
      JSON.stringify(partialDiag.maxillaGroupStatus.detectedIds) === '[3,5]' &&
      JSON.stringify(partialDiag.maxillaGroupStatus.missingIds) === '[4,6]' &&
      partialDiag.mandibleGroupStatus.status === 'PARTIAL' &&
      JSON.stringify(partialDiag.mandibleGroupStatus.detectedIds) === '[7,8,9]' &&
      JSON.stringify(partialDiag.mandibleGroupStatus.missingIds) === '[10]' &&
      partialDiag.detectedCount === 5,
    '14: Partial group states & duplicate ID deduplication report exact unique detected/missing IDs per jaw',
    `max=${JSON.stringify(partialDiag.maxillaGroupStatus)}, mand=${JSON.stringify(partialDiag.mandibleGroupStatus)}`
  );

  // ---------------------------------------------------------------------------
  // 15. Contactless Face Tracking States & Zero Webcam Facial ArUco Requirement
  // ---------------------------------------------------------------------------
  console.log('\n15. Contactless Face Tracking States & Zero Webcam Facial ArUco Requirement');
  const faceOnlyDiag = evaluateArucoPipelineDiagnostic({
    cameraActive: true,
    cameraPoweredOn: true,
    cameraError: null,
    frameDiag: null,
    detectedIds: [],
    faceDetected: true,
  });
  const rimOnlyNoFaceDiag = evaluateArucoPipelineDiagnostic({
    cameraActive: true,
    cameraPoweredOn: true,
    cameraError: null,
    frameDiag: null,
    detectedIds: [3, 4, 5, 6, 7, 8, 9, 10],
    faceDetected: false,
  });
  const noFacialArucoRequired =
    !REGISTERED_ARUCO_IDS.has(0) &&
    !REGISTERED_ARUCO_IDS.has(1) &&
    !REGISTERED_ARUCO_IDS.has(2) &&
    JSON.stringify(CLINICAL_RIM_MARKER_IDS) === '[3,4,5,6,7,8,9,10]' &&
    JSON.stringify(CLINICAL_RIM_EXPECTED_IDS) === '[3,4,5,6,7,8,9,10]' &&
    ![0, 1, 2].some((id) => faceOnlyDiag.missingClinicalIds.includes(id));

  check(
    noFacialArucoRequired &&
      faceOnlyDiag.faceTrackingStatus === 'DETECTED' &&
      rimOnlyNoFaceDiag.faceTrackingStatus === 'NOT_DETECTED' &&
      rimOnlyNoFaceDiag.condition === 'MARKERS_DETECTED',
    '15: Contactless face tracking states are independent of dental-rim ArUco detection; IDs 0–2 are never required in webcam mode',
    `noFacialArucoRequired=${noFacialArucoRequired}`
  );

  // ---------------------------------------------------------------------------
  // 16. Decoded Marker with Low Quality or Imperfect Border Still Reported as Detected
  // ---------------------------------------------------------------------------
  console.log('\n16. Decoded Marker with Low Quality / Imperfect Border Never Reported as Not Detected');
  // 16a: Low-contrast marker (contrast = 18) + 2 corrupted white border cells on a 28px marker
  const lowQualW = 140;
  const lowQualH = 140;
  const lowQualRgba = new Uint8ClampedArray(lowQualW * lowQualH * 4);
  for (let i = 0; i < lowQualRgba.length; i += 4) {
    lowQualRgba[i] = 170;
    lowQualRgba[i + 1] = 170;
    lowQualRgba[i + 2] = 170;
    lowQualRgba[i + 3] = 255;
  }
  const grid3 = getFullMarkerGrid(3).map((r) => [...r]);
  // Flip 2 border cells on the 20-cell perimeter to white (within MAX_BORDER_ERRORS = 7)
  grid3[0][2] = 1;
  grid3[5][3] = 1;
  const decodedImperfect = decodeMarkerGridWithConfidence(grid3, 0, MAX_BORDER_ERRORS);

  const mSize = 30;
  const mx0 = 55;
  const my0 = 55;
  for (let y = my0; y < my0 + mSize; y++) {
    for (let x = mx0; x < mx0 + mSize; x++) {
      const c = Math.min(5, Math.floor(((x - mx0) / mSize) * 6));
      const r = Math.min(5, Math.floor(((y - my0) / mSize) * 6));
      const v = grid3[r][c] === 0 ? 150 : 170; // Low contrast delta = 20
      const idx = (y * lowQualW + x) * 4;
      lowQualRgba[idx] = v;
      lowQualRgba[idx + 1] = v;
      lowQualRgba[idx + 2] = v;
      lowQualRgba[idx + 3] = 255;
    }
  }

  const detLowQual = detectArucoMarkersFromImageData({
    data: lowQualRgba,
    width: lowQualW,
    height: lowQualH,
  });
  const diagLowQual = evaluateArucoPipelineDiagnostic({
    cameraActive: true,
    cameraPoweredOn: true,
    cameraError: null,
    frameDiag: detLowQual,
    detectedIds: detLowQual.detectedIds,
    faceDetected: true,
  });

  check(
    decodedImperfect !== null &&
      decodedImperfect.id === 3 &&
      decodedImperfect.borderWhiteCells === 2 &&
      detLowQual.detectedIds.includes(3) &&
      detLowQual.markerQualities.length === 1 &&
      detLowQual.markerQualities[0].id === 3 &&
      detLowQual.markerQualities[0].borderWhiteCells === 2 &&
      (detLowQual.markerQualities[0].grade === 'LOW' || detLowQual.markerQualities[0].grade === 'POOR') &&
      diagLowQual.condition === 'MARKERS_DETECTED' &&
      diagLowQual.arucoStatusLabel === 'DETECTED',
    '16: Decoded marker with low contrast (delta=20) and 2 white border cells still produces MARKERS_DETECTED with populated MarkerQuality',
    `detectedIds=${JSON.stringify(detLowQual.detectedIds)}, qualities=${JSON.stringify(detLowQual.markerQualities)}, cond=${diagLowQual.condition}`
  );

  // ---------------------------------------------------------------------------
  // 17. Overlay Coordinate Mapping (Cover Crop + Mirroring)
  // ---------------------------------------------------------------------------
  console.log('\n17. Viewport Overlay Coordinate Mapping (Cover Crop + Front-Camera Mirroring)');
  const tfRear = computeCoverTransform(1920, 1080, 1080, 1920, false);
  const ptCenterRear = mapVideoPointToCanvas({ x: 960, y: 540 }, tfRear);
  const tfFront = computeCoverTransform(1920, 1080, 1080, 1920, true);
  const cornersFront = mapVideoCornersToCanvas(
    [
      { x: 1200, y: 400, z: 0 },
      { x: 1300, y: 400, z: 0 },
      { x: 1300, y: 500, z: 0 },
      { x: 1200, y: 500, z: 0 },
    ],
    tfFront
  );
  check(
    Math.abs(ptCenterRear.x - 540) < 0.01 &&
      Math.abs(ptCenterRear.y - 960) < 0.01 &&
      cornersFront[0].x < 540 &&
      cornersFront[1].x < cornersFront[0].x,
    '17: 1920×1080 video-to-canvas cover transform centers optical axis and mirrors X coordinates for front camera',
    `center=(${ptCenterRear.x}, ${ptCenterRear.y}), mirroredC0X=${cornersFront[0].x}`
  );

  console.log('\n====================================================================');
  console.log(`PARITY SUITE SUMMARY: ${passedAssertions} PASSED | ${failedAssertions} FAILED`);
  console.log('====================================================================\n');

  if (failedAssertions > 0) {
    process.exit(1);
  }
}

main();
